// NODE 4. The rubric, as code. Mirrors rubric.json so the two can be diffed.
// Written before any prompt existed. A prompt would be an implementation of
// this, never a replacement for it.

const org = $json.organization || $json;
const form = $('Webhook: Form Submission').item.json;

const facts = {
  company_name:        org.name ?? org.company_name ?? null,
  employee_count:      org.estimated_num_employees ?? org.employee_count ?? null,
  industry:            org.industry ?? null,
  hq_country:          org.country ?? org.hq_country ?? null,
  tech_stack:          org.technology_names ?? org.tech_stack ?? [],
  requested_demo:      form.requested_demo ?? null,
  pricing_page_visits: form.pricing_page_visits ?? null,
  emails_opened:       form.emails_opened ?? null,
};

const WAREHOUSES = ['snowflake', 'bigquery', 'redshift', 'databricks', 'synapse'];
const ICP        = ['healthcare', 'fintech', 'saas'];
const SELL_TO    = ['United States','Canada','United Kingdom','Germany',
                    'Australia','Netherlands','Ireland','Sweden'];

const missing = v => v === null || v === undefined || v === '';

const criteria = [
  { id:'employee_count_in_band', pts:20, field:'employee_count',
    met: v => typeof v === 'number' && v >= 100 && v <= 2000 },
  { id:'industry_in_icp',        pts:20, field:'industry',
    met: v => typeof v === 'string' && ICP.some(k => v.toLowerCase().includes(k)) },
  { id:'has_cloud_warehouse',    pts:10, field:'tech_stack',
    met: v => Array.isArray(v) && WAREHOUSES.some(k => v.join(' ').toLowerCase().includes(k)) },
  { id:'sellable_country',       pts:10, field:'hq_country',
    met: v => SELL_TO.includes(v) },
  { id:'requested_demo',         pts:25, field:'requested_demo',
    met: v => v === true },
  { id:'pricing_page_repeat',    pts:10, field:'pricing_page_visits',
    met: v => typeof v === 'number' && v >= 2 },
  { id:'email_engagement',       pts:5,  field:'emails_opened',
    met: v => typeof v === 'number' && v >= 3 },
];

const ABSTAIN_AT = 20;
let score = 0;
const blocking = [];
const breakdown = [];

for (const c of criteria) {
  const value = facts[c.field];
  if (missing(value)) {
    if (c.pts >= ABSTAIN_AT) blocking.push(c.field);
    breakdown.push({ id: c.id, verdict: 'missing', awarded: 0, available: c.pts });
    continue;
  }
  const hit = c.met(value);
  const awarded = hit ? c.pts : 0;
  score += awarded;
  breakdown.push({ id: c.id, verdict: hit ? 'met' : 'not met', awarded, available: c.pts });
}

// Missing data is not zero. This branch is the design decision worth defending.
let route;
if (blocking.length)      route = 'abstain';
else if (score >= 70)     route = 'book a call';
else if (score >= 40)     route = 'nurture';
else                      route = 'disqualify';

const DESTINATION = {
  'book a call': 'sales_queue',
  'nurture':     'nurture_sequence',
  'disqualify':  'closed_lost',
  'abstain':     'needs_human',
};

return {
  json: {
    lead_email: form.email,
    company: facts.company_name,
    score,
    route,
    destination: DESTINATION[route],
    missing_blocking_fields: blocking,
    breakdown,
    decided_at: new Date().toISOString(),
  }
};

// NODE 5. The error branch, which exists so a failure does not silently
// stop the whole run. Enrichment missed, so this lead goes to a person with
// the reason attached rather than being scored on absent data.

const form = $('Webhook: Form Submission').item.json;
const upstream = $json;

return {
  json: {
    lead_email: form.email,
    contact_name: form.contact_name ?? null,
    route: 'abstain',
    destination: 'needs_human',
    reason: 'enrichment did not resolve a company for this domain',
    domain: (form.email || '').split('@')[1] ?? null,
    provider_status: upstream.error ?? upstream.message ?? 'no company_name returned',
    raised_at: new Date().toISOString(),
    // Attach a Google Sheets node here to append, and a Slack node to notify.
    // Both are left off so this file imports with no credentials configured.
    next_action: 'append to needs_human sheet, notify #gtm-inbound',
  }
};
